select 
  from ry_business.ry_rental_media_asset m
  left join ry_business.ry_rental_order o on o.order_id = m.order_id
 where m.tenant_id = #{tenantId}
   and m.member_id = #{memberId}
   and m.order_id = #{orderId}
   and m.is_delete = 0
 order by m.create_time desc, m.media_id desc

