mapper.update:
update ry_business.ry_rental_media_asset
   set order_id = #{orderId}, unit_id = #{unitId}, sn_id = #{snId}, detected_sn = #{detectedSn},
       match_status = #{matchStatus}, update_by = #{operatorId}, update_time = now()
 where tenant_id = #{tenantId}
   and member_id = #{memberId}
   and media_id = #{mediaId}
   and is_delete = 0

mapper.select:
select candidate.orderId, candidate.orderNo, candidate.warehouseId,
       candidate.unitId, candidate.snId, candidate.snCode
  from (
        select o.order_id as orderId, o.order_no as orderNo, o.warehouse_id as warehouseId,
               inventory_unit.unit_id as unitId, null as snId,
               inventory_unit.serial_number as snCode, o.lease_start_date as leaseStartDate
          from ry_business.ry_rental_order o
          inner join ry_business.ry_rental_merchant_inventory_unit inventory_unit
             on inventory_unit.tenant_id = o.tenant_id
            and inventory_unit.member_id = o.member_id
            and inventory_unit.is_delete = 0
            and inventory_unit.serial_number = #{detectedSn}
         where o.tenant_id = #{tenantId}
           and o.member_id = #{memberId}
           and o.is_delete = 0
           and json_search(
                 coalesce(o.package_details_json, json_object()),
                 'one', cast(inventory_unit.unit_id as char), null,
                 '$.items[*].unitIds[*]'
               ) is not null
           and o.order_status in

            #{orderStatus}

        union all
        select o.order_id as orderId, o.order_no as orderNo, o.warehouse_id as warehouseId,
               null as unitId, oi.sn_id as snId, s.sn_code as snCode,
               o.lease_start_date as leaseStartDate
          from ry_business.ry_rental_order o
          inner join ry_business.ry_rental_order_item oi on oi.order_id = o.order_id
          inner join ry_business.ry_rental_asset_sn s on s.sn_id = oi.sn_id
         where o.tenant_id = #{tenantId}
           and o.member_id = #{memberId}
           and o.is_delete = 0
           and oi.tenant_id = #{tenantId}
           and oi.member_id = #{memberId}
           and oi.is_delete = 0
           and s.tenant_id = #{tenantId}
           and s.member_id = #{memberId}
           and s.is_delete = 0
           and s.sn_code = #{detectedSn}
           and o.order_status in

            #{orderStatus}

       ) candidate
 order by candidate.leaseStartDate desc, candidate.orderId desc
 limit 1

select o.order_id as orderId, o.order_no as orderNo, o.warehouse_id as warehouseId,
       oi.sn_id as snId, s.sn_code as snCode
  from ry_business.ry_rental_order o
  inner join ry_business.ry_rental_order_item oi on oi.order_id = o.order_id
  inner join ry_business.ry_rental_asset_sn s on s.sn_id = oi.sn_id
 where o.tenant_id = #{tenantId}
   and o.member_id = #{memberId}
   and o.order_id = #{orderId}
   and oi.sn_id = #{snId}
   and o.is_delete = 0
   and oi.is_delete = 0
   and s.tenant_id = #{tenantId}
   and s.member_id = #{memberId}
   and s.is_delete = 0
   and o.order_status in

    #{orderStatus}

 limit 1
